// R7 (bonus): one row per summarisation method.
// Merge (Append) keeps the input order: 1 = Stuff, 2 = Refine, 3 = Map Reduce.
const methods = ['Stuff', 'Refine', 'Map Reduce'];
const size = 500, overlap = 100; // same values as the three chain nodes
const text = $('Prepare Comparison Input').first().json.allNotes;
// Rough estimate: the chains split the item's JSON text, so the real chunk count can differ a little.
const chunks = Math.max(1, Math.ceil((text.length - overlap) / (size - overlap)));
const calls = [1, chunks, chunks + 1]; // Stuff: 1 call; Refine: one per chunk, sequential; Map Reduce: one per chunk + 1 combine
return $input.all().map((item, i) => {
  // The chain returns an object: {text} (Stuff, Map Reduce) or {output_text} (Refine).
  const raw = item.json.response ?? item.json.output ?? '';
  const summary = typeof raw === 'string' ? raw : (raw.text ?? raw.output_text ?? JSON.stringify(raw));
  return { json: { method: methods[i], estimatedChunks: chunks, estimatedLlmCalls: calls[i], summaryChars: summary.length, summary } };
});
